#!/usr/bin/env node
/**
 * Compile the desktop app's CHANGELOG.md into src/data/changelog.generated.ts.
 *
 *   npm run compile:changelog             # read the desktop checkout, rewrite the generated file
 *   npm run compile:changelog -- --check  # fail when the generated file no longer matches the desktop
 *
 * The desktop CHANGELOG.md (Keep a Changelog) is the source of truth for what
 * shipped. Sections map to the site's ChangeType (Added -> feature, Changed ->
 * improvement, Fixed -> fix, Removed -> breaking). Only bullets that open with a
 * bold lead sentence (`- **Lead.** detail`) are public-facing; the lead becomes
 * `text`. Un-bolded bullets are the internal voice and are dropped. Each release
 * keeps at most MAX_PER_RELEASE items, breaking first, so the timeline reads.
 *
 * The output is generated, never hand-edited. It is NOT yet wired into RELEASES
 * in changelog.ts: that swap waits for the desktop to cut versioned sections at
 * tag time (until then everything since 0.4.0 is one [Unreleased] block).
 *
 * The desktop checkout resolves as in scripts/sync-desktop-facts.mjs. --check
 * exits 0 with "skipped" when none exists (a fresh clone, CI), 1 on drift.
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { writeFileAtomic } from "./atomic-write.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "..");
export const OUT_PATH = path.join(REPO_ROOT, "src", "data", "changelog.generated.ts");
export const MAX_PER_RELEASE = 12;

const SECTION_TYPE = { added: "feature", changed: "improvement", fixed: "fix", removed: "breaking" };
const TYPE_ORDER = ["breaking", "feature", "improvement", "fix"];

/** `**Lead sentence.** rest` -> "Lead sentence" (trailing period/colon dropped), else null. */
export function leadOf(bullet) {
  const m = /^\*\*(.+?)\*\*/.exec(bullet.trim());
  if (!m) return null;
  const lead = m[1].replace(/[.:\s]+$/, "").trim();
  return lead || null;
}

/** Top-level bullets of a block, continuation lines folded in. */
function bulletsOf(lines) {
  const out = [];
  for (const line of lines) {
    if (/^- /.test(line)) out.push(line.slice(2));
    else if (out.length && /^\s+\S/.test(line)) out[out.length - 1] += " " + line.trim();
  }
  return out;
}

/** Parse the changelog text into [{ version, date, changes }] in document order. */
export function parseChangelog(text) {
  const releases = [];
  let rel = null;
  let type = null;
  let buf = [];
  const flush = () => {
    if (rel && type) {
      for (const b of bulletsOf(buf)) {
        const lead = leadOf(b);
        if (lead) rel.changes.push({ text: lead, type });
      }
    }
    buf = [];
  };
  for (const raw of text.replace(/\r\n/g, "\n").split("\n")) {
    const h2 = /^## \[([^\]]+)\](?:\s*[—-]\s*(\S+))?/.exec(raw);
    if (h2) {
      flush();
      type = null;
      const name = h2[1];
      const isVersion = /^\d+\.\d+\.\d+$/.test(name);
      rel = /^unreleased$/i.test(name) || isVersion ? { version: isVersion ? name : "Unreleased", date: h2[2] ?? "", changes: [] } : null;
      if (rel) releases.push(rel);
      continue;
    }
    const h3 = /^### (.+?)\s*$/.exec(raw);
    if (h3) {
      flush();
      type = SECTION_TYPE[h3[1].toLowerCase()] ?? null;
      continue;
    }
    buf.push(raw);
  }
  flush();
  return releases.map((r) => {
    const seen = new Set();
    const unique = r.changes.filter((c) => (seen.has(c.text) ? false : seen.add(c.text)));
    const sorted = TYPE_ORDER.flatMap((t) => unique.filter((c) => c.type === t));
    return { ...r, total: unique.length, changes: sorted.slice(0, MAX_PER_RELEASE) };
  });
}

/** The generated module text for a parsed changelog. Deterministic. */
export function render(releases) {
  const body = releases
    .filter((r) => r.changes.length)
    .map((r) => {
      const items = r.changes.map((c) => `      { text: ${JSON.stringify(c.text)}, type: ${JSON.stringify(c.type)} },`).join("\n");
      return `  {\n    version: ${JSON.stringify(r.version)},\n    date: ${JSON.stringify(r.date)},\n    totalPublic: ${r.total},\n    changes: [\n${items}\n    ],\n  },`;
    })
    .join("\n");
  return `/* Generated by scripts/compile-changelog.mjs from the desktop CHANGELOG.md - do not hand-edit; run npm run compile:changelog. */

import type { ChangeItem } from "./changelog";

export interface CompiledRelease {
  version: string;
  /** Empty for the [Unreleased] block. */
  date: string;
  /** Public (bold-lead) items in the section before the per-release cap. */
  totalPublic: number;
  changes: ChangeItem[];
}

export const COMPILED_RELEASES: CompiledRelease[] = [
${body}
];
`;
}

function resolveDesktop() {
  const isRepo = (p) => Boolean(p) && fs.existsSync(path.join(p, ".git"));
  const override = process.env.PERSONAS_DESKTOP_REPO;
  if (override) {
    return isRepo(override)
      ? { path: override, explicit: true }
      : { path: null, explicit: true, reason: `PERSONAS_DESKTOP_REPO="${override}" is not a git checkout` };
  }
  const candidates = [path.resolve(REPO_ROOT, "../personas"), path.resolve(REPO_ROOT, "../../../../personas")];
  for (const c of candidates) if (isRepo(c)) return { path: c, explicit: false };
  return { path: null, explicit: false, reason: `no desktop checkout (looked in ${candidates.join(", ")})` };
}

function main() {
  const check = process.argv.slice(2).includes("--check");
  const desktop = resolveDesktop();
  if (!desktop.path) {
    if (check && !desktop.explicit) {
      console.log(`compile-changelog: skipped - ${desktop.reason}; set PERSONAS_DESKTOP_REPO to check drift.`);
      process.exit(0);
    }
    console.error(`compile-changelog: ${desktop.reason}`);
    process.exit(1);
  }
  const src = fs.readFileSync(path.join(desktop.path, "CHANGELOG.md"), "utf8");
  const out = render(parseChangelog(src));
  if (check) {
    const cur = fs.existsSync(OUT_PATH) ? fs.readFileSync(OUT_PATH, "utf8").replace(/\r\n/g, "\n") : "";
    if (cur === out) {
      console.log(`compile-changelog: in sync with ${desktop.path}`);
      process.exit(0);
    }
    console.error("compile-changelog: DRIFT between the desktop CHANGELOG.md and src/data/changelog.generated.ts; run `npm run compile:changelog` and commit it.");
    process.exit(1);
  }
  writeFileAtomic(OUT_PATH, out);
  const rs = parseChangelog(src);
  for (const r of rs) console.log(`  ${r.version}: ${r.total} public items, kept ${r.changes.length}`);
  console.log(`compile-changelog: wrote ${path.relative(REPO_ROOT, OUT_PATH)} from ${desktop.path}`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
